# ---------------------------------------------------------------------------
# Safety boundaries: paths this script must NEVER touch
# ---------------------------------------------------------------------------
_FORBIDDEN_PREFIXES = ("data/", "logs/", ".venv/", "venv/", ".git/", "sample_source/", "__pycache__/")
_FORBIDDEN_EXACT = {".env"}

# Markers that must already exist for a candidate directory to look like a
# real, previous-version company-knowledge-search project root.
REQUIRED_MARKERS = [
    "app.py",
    "src/config.py",
    "src/search.py",
    "src/database.py",
    "src/models.py",
    "requirements.txt",
    "start.bat",
]

# Packages this version requires, mapped to their importable module name.
DEPENDENCIES = [
    ("pymupdf", "fitz", "hard"),
    ("python-pptx", "pptx", "hard"),
    ("python-docx", "docx", "hard"),
    ("streamlit", "streamlit", "hard"),
    ("openpyxl", "openpyxl", "soft"),
    ("numpy", "numpy", "hard"),
]

DEFAULT_JAN_URL = "http://127.0.0.1:1337/v1"
DEFAULT_EMBEDDING_URL = "http://127.0.0.1:8081/v1/embeddings"


def log(message: str = "") -> None:
    print(message, flush=True)


def fail(message: str) -> None:
    log(f"ERROR: {message}")
    sys.exit(1)


# ---------------------------------------------------------------------------
# Step: locate the project
# ---------------------------------------------------------------------------

def looks_like_project_root(path: Path) -> bool:
    return path.is_dir() and all((path / marker).exists() for marker in REQUIRED_MARKERS)


def describe_markers(path: Path) -> None:
    for marker in REQUIRED_MARKERS:
        mark = "OK" if (path / marker).exists() else "MISSING"
        log(f"    [{mark}] {marker}")


def candidate_roots() -> list:
    candidates = []
    seen = set()

    def add(path: Path):
        try:
            resolved = path.resolve()
        except OSError:
            return
        if resolved not in seen:
            seen.add(resolved)
            candidates.append(resolved)

    add(SCRIPT_PATH.parent)
    for ancestor in SCRIPT_PATH.parents:
        add(ancestor / "company-knowledge-search")
    add(Path.cwd())
    add(Path.cwd() / "company-knowledge-search")
    home = Path.home()
    for base in (home, home / "Desktop", home / "Documents", home / "Downloads"):
        add(base / "company-knowledge-search")

    return candidates


def locate_project_root() -> Path:
    log("Looking for an existing company-knowledge-search installation...")
    found = [c for c in candidate_roots() if looks_like_project_root(c)]
    if len(found) == 1:
        log(f"  Found: {found[0]}")
        return found[0]
    if len(found) > 1:
        log("  Found more than one possible installation:")
        for i, path in enumerate(found, start=1):
            log(f"    {i}. {path}")
        while True:
            choice = input(f"  Enter the number of the correct one (1-{len(found)}): ").strip()
            if choice.isdigit() and 1 <= int(choice) <= len(found):
                return found[int(choice) - 1]
            log("  Not a valid choice, try again.")

    log("  Could not find it automatically.")
    for attempt in range(3):
        typed = input("Enter the full path to your company-knowledge-search folder: ").strip().strip('"')
        if not typed:
            continue
        candidate = Path(typed)
        if looks_like_project_root(candidate):
            return candidate.resolve()
        log(f"  That folder does not look like a company-knowledge-search project root:")
        describe_markers(candidate)
        log("  Make sure it is the folder that directly contains app.py.")
    fail("Could not locate a valid project folder after 3 attempts. Re-run this script from (or next to) the correct folder.")


# ---------------------------------------------------------------------------
# Step: backup / write / rollback
# ---------------------------------------------------------------------------

def hash_file(path: Path):
    if not path.exists():
        return None
    return hashlib.sha256(path.read_bytes()).hexdigest()


def unique_backup_dir(root: Path) -> Path:
    timestamp = time.strftime("%Y%m%d_%H%M%S")
    base = root / f"backup_before_hybrid_rag_{timestamp}"
    candidate = base
    suffix = 1
    while candidate.exists():
        suffix += 1
        candidate = root / f"{base.name}_{suffix}"
    return candidate


def write_files(root: Path, backup_dir: Path) -> list:
    written = []
    for rel, encoded in FILES.items():
        dest = root / rel
        existed = dest.exists()
        if existed:
            backup_dest = backup_dir / rel
            backup_dest.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(dest, backup_dest)
        dest.parent.mkdir(parents=True, exist_ok=True)
        raw_bytes = base64.b64decode(encoded)
        if rel.endswith((".bat", ".vbs")):
            text = raw_bytes.decode("utf-8").replace("\r\n", "\n").replace("\n", "\r\n")
            raw_bytes = text.encode("utf-8")
        dest.write_bytes(raw_bytes)
        written.append((rel, existed))
        log(f"    {'updated' if existed else 'added  '} {rel}")
    return written


def rollback_files(root: Path, backup_dir: Path, written: list) -> None:
    log("  Restoring previous application files from backup...")
    for rel, existed in written:
        dest = root / rel
        if existed:
            backup_src = backup_dir / rel
            if backup_src.exists():
                dest.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(backup_src, dest)
                log(f"    restored {rel}")
            else:
                log(f"    WARNING: no backup found for {rel}; left as written")
        else:
            if dest.exists():
                dest.unlink()
                log(f"    removed {rel} (was newly added by this update)")
    log(f"  Previous application files restored. Backup kept at: {backup_dir}")


def compile_check(root: Path, written: list) -> None:
    for rel, _existed in written:
        if rel.endswith(".py"):
            try:
                py_compile.compile(str(root / rel), doraise=True)
            except py_compile.PyCompileError as exc:
                raise RuntimeError(f"{rel} failed to compile:\n{exc}") from exc
    log("  Python syntax check passed for all updated files.")


# ---------------------------------------------------------------------------
# Step: dependencies
# ---------------------------------------------------------------------------

def is_importable(module_name: str) -> bool:
    try:
        return importlib.util.find_spec(module_name) is not None
    except (ImportError, ValueError):
        return False


def check_dependencies(attempt_install: bool = True) -> dict:
    report = {}
    missing_hard = []
    for package, module_name, tier in DEPENDENCIES:
        report[package] = {"module": module_name, "tier": tier, "status": "OK" if is_importable(module_name) else "MISSING"}
        if report[package]["status"] == "MISSING" and tier == "hard":
            missing_hard.append((package, module_name))

    if missing_hard and attempt_install:
        log("  Missing required package(s), attempting offline-safe install (pip cache/wheel only if available)...")
        for package, module_name in missing_hard:
            log(f"    installing {package}...")
            try:
                proc = subprocess.run(
                    [sys.executable, "-m", "pip", "install", "--disable-pip-version-check", "--no-input", package],
                    capture_output=True,
                    text=True,
                    timeout=25,
                )
                ok = proc.returncode == 0 and is_importable(module_name)
            except (subprocess.TimeoutExpired, OSError):
                ok = False
            report[package]["status"] = "OK" if ok else "MISSING"
            report[package]["install_attempted"] = True
            if not ok:
                log(f"    could not install {package} automatically (likely no internet access).")

    return report


def missing_hard_modules(dep_report: dict) -> set:
    return {info["module"] for pkg, info in dep_report.items() if info["tier"] == "hard" and info["status"] == "MISSING"}


# ---------------------------------------------------------------------------
# Step: import validation (isolated sandbox copy, never touches real data)
# ---------------------------------------------------------------------------

def sandbox_import_check(root: Path, known_missing: set) -> str:
    """Returns 'OK', 'SKIPPED', or raises RuntimeError on an unexpected
    failure (anything other than an already-reported missing dependency)."""
    check_code = (
        "import app\n"
        "import src.config as _cfg\n"
        "assert hasattr(_cfg, 'migrate_config')\n"
        "import src.search\n"
        "import src.formatting\n"
        "import src.conversations\n"
        "import src.folder_picker\n"
        "import src.embedding_format\n"
        "import src.embedding_index\n"
        "import src.embedding_provider\n"
        "import src.hybrid_retrieval\n"
        "import src.llm_provider\n"
        "import src.rag_pipeline\n"
        "import src.rag_prompt\n"
        "import src.reranking\n"
        "import src.temporal\n"
        "import src.parsers.excel\n"
        "import src.database as _db\n"
        "assert hasattr(_db, 'initialize_schema')\n"
        "from src.llm_provider import ProviderGenerationLimitError as _gle\n"
        "assert issubclass(_gle, Exception)\n"
        "import scripts.ensure_local_services as _launcher\n"
        "assert hasattr(_launcher, 'ensure_jan') and hasattr(_launcher, 'ensure_embedding')\n"
        "print('SANDBOX_IMPORT_OK')\n"
    )
    with tempfile.TemporaryDirectory(prefix="cks_rag_check_") as tmp:
        tmp_path = Path(tmp)
        shutil.copy2(root / "app.py", tmp_path / "app.py")
        shutil.copytree(root / "src", tmp_path / "src", ignore=shutil.ignore_patterns("__pycache__"))
        shutil.copytree(root / "scripts", tmp_path / "scripts", ignore=shutil.ignore_patterns("__pycache__"))
        try:
            proc = subprocess.run(
                [sys.executable, "-c", check_code],
                cwd=str(tmp_path),
                capture_output=True,
                text=True,
                timeout=90,
            )
        except subprocess.TimeoutExpired as exc:
            raise RuntimeError("post-update import check timed out after 90s") from exc

    if proc.returncode == 0 and "SANDBOX_IMPORT_OK" in proc.stdout:
        return "OK"

    stderr = proc.stderr or ""
    if known_missing and any(f"No module named '{mod}'" in stderr for mod in known_missing):
        return "SKIPPED"
    raise RuntimeError(f"post-update import check failed (exit {proc.returncode}):\n{stderr[-4000:]}")


# ---------------------------------------------------------------------------
# Step: database migration (runs against the REAL database, on purpose --
# this is the application's own idempotent, additive-only migration code)
# ---------------------------------------------------------------------------

def resolve_db_path(root: Path) -> Path:
    config_path = root / "data" / "config.json"
    if config_path.exists():
        try:
            raw = json.loads(config_path.read_text(encoding="utf-8"))
            db_path = raw.get("db_path")
            if db_path:
                candidate = Path(db_path)
                return candidate if candidate.is_absolute() else (root / candidate)
        except (OSError, json.JSONDecodeError):
            pass
    return root / "data" / "knowledge.db"


def load_database_module(root: Path):
    root_str = str(root)
    if root_str not in sys.path:
        sys.path.insert(0, root_str)
    for name in list(sys.modules):
        if name == "src" or name.startswith("src."):
            del sys.modules[name]
    return importlib.import_module("src.database")


def table_columns(conn: sqlite3.Connection, table: str) -> list:
    return [row["name"] for row in conn.execute(f"PRAGMA table_info({table})") ]


def table_snapshot(conn: sqlite3.Connection, table: str, columns: list) -> str:
    column_list = ", ".join(columns)
    rows = conn.execute(f"SELECT {column_list} FROM {table} ORDER BY id").fetchall()
    return hashlib.sha256(repr([tuple(row) for row in rows]).encode("utf-8")).hexdigest()


def migrate_database(root: Path, backup_dir: Path) -> dict:
    db_path = resolve_db_path(root)
    result = {"db_path": str(db_path), "existed_before": db_path.exists()}

    if not db_path.exists():
        log(f"  No existing database at {db_path} -- nothing to migrate (a fresh one will be created on first run).")
        return result

    backup_db_dir = backup_dir / "data"
    backup_db_dir.mkdir(parents=True, exist_ok=True)
    shutil.copy2(db_path, backup_db_dir / db_path.name)
    log(f"  Backed up database to {backup_db_dir / db_path.name}")

    db_module = load_database_module(root)
    conn = db_module.connect(db_path)
    try:
        has_documents = conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='documents'"
        ).fetchone() is not None
        has_chunks = conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='chunks'"
        ).fetchone() is not None
        documents_columns = table_columns(conn, "documents") if has_documents else []
        chunks_columns = table_columns(conn, "chunks") if has_chunks else []
        stable_documents_columns = [c for c in documents_columns if c not in {"document_date", "document_date_source"}]
        before_documents = table_snapshot(conn, "documents", stable_documents_columns) if has_documents else None
        before_chunks = table_snapshot(conn, "chunks", chunks_columns) if has_chunks else None
        before_doc_count = conn.execute("SELECT COUNT(*) FROM documents").fetchone()[0] if has_documents else 0
        before_chunk_count = conn.execute("SELECT COUNT(*) FROM chunks").fetchone()[0] if has_chunks else 0

        db_module.initialize_schema(conn)

        after_doc_count = conn.execute("SELECT COUNT(*) FROM documents").fetchone()[0]
        after_chunk_count = conn.execute("SELECT COUNT(*) FROM chunks").fetchone()[0]
        after_documents = table_snapshot(conn, "documents", stable_documents_columns) if has_documents else None
        after_chunks = table_snapshot(conn, "chunks", chunks_columns) if has_chunks else None
        has_chunk_embeddings = conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name='chunk_embeddings'"
        ).fetchone() is not None
    finally:
        conn.close()

    if before_documents is not None and before_documents != after_documents:
        raise RuntimeError("existing 'documents' rows changed during migration -- aborting.")
    if before_chunks is not None and before_chunks != after_chunks:
        raise RuntimeError("existing 'chunks' rows changed during migration -- aborting.")
    if before_doc_count != after_doc_count or before_chunk_count != after_chunk_count:
        raise RuntimeError("row counts changed during migration -- aborting.")
    if not has_chunk_embeddings:
        raise RuntimeError("chunk_embeddings table was not created by migration.")

    result.update(
        {
            "documents_preserved": before_doc_count,
            "chunks_preserved": before_chunk_count,
            "chunk_embeddings_present": True,
            "backup_copy": str(backup_db_dir / db_path.name),
        }
    )
    log(f"  Migration applied: {before_doc_count} document(s) / {before_chunk_count} chunk(s) preserved unchanged.")
    log("  chunk_embeddings table present.")
    return result


def rollback_database(migration_result: dict) -> None:
    if not migration_result or not migration_result.get("backup_copy"):
        return
    backup_copy = Path(migration_result["backup_copy"])
    db_path = Path(migration_result["db_path"])
    if backup_copy.exists():
        shutil.copy2(backup_copy, db_path)
        log(f"  Restored database from backup: {db_path}")


# ---------------------------------------------------------------------------
# Step: config migration (idempotent 420 -> 700, preserves custom values)
# ---------------------------------------------------------------------------

def migrate_config_file(root: Path) -> dict:
    """Apply idempotent config migrations to data/config.json.

    Currently migrates:
      - jan_max_tokens: 420 (legacy default) -> 700 (safe default)

    Only the exact legacy default value is changed; user-customised
    values are preserved. Returns a report dict."""
    config_path = root / "data" / "config.json"
    result = {"migrated": False, "details": []}
    if not config_path.exists():
        result["details"].append("No config.json found (safe defaults will apply on first run).")
        return result
    try:
        raw = json.loads(config_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        result["details"].append("Could not parse config.json -- skipping config migration.")
        return result

    if not isinstance(raw, dict):
        return result

    if raw.get("jan_max_tokens") == 420:
        raw["jan_max_tokens"] = 700
        result["migrated"] = True
        result["details"].append("jan_max_tokens: 420 -> 700 (legacy default migrated)")
    elif "jan_max_tokens" in raw:
        result["details"].append(f"jan_max_tokens: {raw['jan_max_tokens']} (custom value preserved)")
    else:
        result["details"].append("jan_max_tokens: not present (default 700 applies)")

    if result["migrated"]:
        config_path.write_text(
            json.dumps(raw, indent=2, ensure_ascii=False),
            encoding="utf-8",
        )

    return result


def describe_config_status(root: Path) -> None:
    config_path = root / "data" / "config.json"
    if not config_path.exists():
        log("  No existing data/config.json found (will be created with safe defaults on first run).")
        return
    log(f"  Existing data/config.json found: {config_path}")


# ---------------------------------------------------------------------------
# Step: informational local-service reachability (never blocks update)
# ---------------------------------------------------------------------------

def probe_local_service(url: str, timeout: float = 0.35) -> str:
    try:
        parsed = urlparse(url)
        host = parsed.hostname or "127.0.0.1"
        port = parsed.port or (443 if parsed.scheme == "https" else 80)
        with socket.create_connection((host, port), timeout=timeout):
            return "ONLINE"
    except OSError:
        return "NOT TESTED / OFFLINE"


def read_configured_urls(root: Path) -> tuple:
    config_path = root / "data" / "config.json"
    jan_url, embedding_url = DEFAULT_JAN_URL, DEFAULT_EMBEDDING_URL
    if config_path.exists():
        try:
            raw = json.loads(config_path.read_text(encoding="utf-8"))
            jan_url = raw.get("jan_base_url") or jan_url
            embedding_url = raw.get("embedding_base_url") or embedding_url
        except (OSError, json.JSONDecodeError):
            pass
    return jan_url, embedding_url


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------

def main() -> None:
    assert all(
        not rel.startswith(_FORBIDDEN_PREFIXES) and rel not in _FORBIDDEN_EXACT for rel in FILES
    ), "internal error: payload references a protected path"

    log("CS&P RAG — Hybrid RAG Updater (v015, 20260821, 352 tests)")
    log("=" * 48)
    log()

    root = locate_project_root()
    log(f"[1/7] Existing project found: {root}")
    log()

    backup_dir = unique_backup_dir(root)
    log(f"[2/7] Creating backup: {backup_dir.name}")

    log()
    log("[3/7] Updating application files")
    written = []
    migration_result = {}
    try:
        written = write_files(root, backup_dir)
        compile_check(root, written)

        log()
        log("[4/7] Applying safe schema migration")
        migration_result = migrate_database(root, backup_dir)
        describe_config_status(root)

        log()
        log("[5/7] Applying config migration")
        config_migration_result = migrate_config_file(root)
        for detail in config_migration_result["details"]:
            log(f"  {detail}")

        log()
        log("[6/7] Running validation")
        dep_report = check_dependencies(attempt_install=True)
        known_missing = missing_hard_modules(dep_report)
        import_status = sandbox_import_check(root, known_missing)

    except Exception as exc:  # noqa: BLE001 -- any failure triggers rollback
        log()
        log(f"UPDATE FAILED: {exc}")
        log()
        log("Rolling back...")
        rollback_database(migration_result)
        rollback_files(root, backup_dir, written)
        log()
        log("Application update: FAIL")
        log("No changes were kept. Your previous installation is unchanged.")
        log(f"Details of the attempted update are in: {backup_dir}")
        sys.exit(1)

    has_start_bat = (root / "start.bat").exists()
    has_setup_bat = (root / "setup.bat").exists()
    has_ico = (root / "app.ico").exists()
    has_png = (root / "app_icon.png").exists()
    has_vbs = (root / "create_desktop_shortcut.vbs").exists()

    log()
    log("[7/7] Update complete")
    log()
    log("=" * 48)
    if import_status == "OK":
        log("Application update: PASS")
    else:
        log("Application update: PASS (files + database) / dependencies incomplete")
    log()
    log("Dependency check:")
    for package, info in dep_report.items():
        note = "" if info["tier"] == "hard" else "  (optional -- only needed for Excel documents)"
        log(f"  {package:<14} {info['status']}{note}")
    if known_missing:
        log()
        log("  Could not confirm these are importable in this environment:")
        for mod in sorted(known_missing):
            log(f"    - {mod}")
        log("  Install them (e.g. 'py -m pip install <package>') before launching the app,")
        log("  or transfer the matching offline wheel file if this machine has no internet access.")

    log()
    jan_url, embedding_url = read_configured_urls(root)
    log(f"Jan server ({jan_url}): {probe_local_service(jan_url)}")
    log(f"Embedding server ({embedding_url}): {probe_local_service(embedding_url)}")
    log("(Servers being offline right now is expected and is not a failure --")
    log(" they only need to be running when you actually use the app.)")

    log()
    log(f"Startup scripts: start.bat {'OK' if has_start_bat else 'MISSING'}, setup.bat {'OK' if has_setup_bat else 'MISSING'}")
    log(f"Desktop assets: app.ico {'OK' if has_ico else 'MISSING'}, app_icon.png {'OK' if has_png else 'MISSING'}, create_desktop_shortcut.vbs {'OK' if has_vbs else 'MISSING'}")
    log(f"Backup of replaced files and pre-migration database: {backup_dir}")

    log()
    log("Next:")
    log("1. Run start.bat -- it now starts Jan and EmbeddingGemma for you")
    log("   (if their paths are configured in 進階設定), waits for them to")
    log("   become ready, brings the semantic index up to date, then opens")
    log("   CS&P RAG. If a service is still offline, the app opens anyway")
    log("   and clearly shows which one, in degraded mode.")
    log("2. Double-click create_desktop_shortcut.vbs once to add")
